using System.Text;

namespace Open.Database.Extensions.Generator;

// Writes the one generated file. Shape (SG.md section 2, through the existing public overloads only: no hook in Core):
//   - per call site, an interceptor: Map_n(this <receiver> x) => CoreExtensions.Map<T>(x, new M_T().Row), the existing Map(Func<IDataRecord, T>) overload;
//   - per model type, a binder class M_T: its Row method is the selector. It binds once per reader (and again when the column count changes),
//     against a small static cache of the layouts met lately, and then reads every row with typed getters in one of five read modes.
//   - errors: each row reader (one per read mode) is ONE try region around the whole row (reads, construction, sets), entered once per row; its
//     handler is cold and does no reader work. Anything but a DbException or an OperationCanceledException (RowMap.Guard's filter: those pass
//     through untouched) is thrown as a ValueMappingException naming the model type and the row (its 0-based index among the rows mapped: Bound.Rows,
//     one increment per row), the exception inside. No member or column is named (the runtime map names them; tracking the cell would put work
//     on the hot path), and the report is the same on a SequentialAccess reader. A layout the runtime serves (mode 0) reports as the runtime does.
//   - NULL, by the member's type: a member declared non-nullable (a value type other than Nullable<T>, a reference annotated non-nullable) is read
//     with its typed getter alone, as a hand-written selector reads it; a NULL there is exceptional: the provider's getter throws (ProviderNullTests)
//     and the row's handler reports it. A nullable member (int?, string?, a reference in code with nullable annotations off, object) is tested
//     with IsDBNull and gets null. (The runtime map keeps a non-nullable member's value on a NULL instead; whether it takes this rule too is open.)
//   - a layout the generated code does not serve is mapped by the runtime RowMap<T> (through its public, hidden ArrayMapper, the route to its
//     object[] row reader), so the rows, and the exceptions, are the runtime's.
static class Emitter
{
	const string Ns = "global::Open.Database.Extensions";
	const string DbReader = "global::System.Data.Common.DbDataReader";
	const string Record = "global::System.Data.IDataRecord";
	const string TypeT = "global::System.Type";

	public static string Emit(IReadOnlyList<Site> sites, Options options)
	{
		var sb = new StringBuilder();
		sb.AppendLine("// <auto-generated/>");
		sb.AppendLine("// Open.Database.Extensions source generator (prototype): Map<T>() served by generated row readers.");
		sb.AppendLine("#nullable disable");
		sb.AppendLine("#pragma warning disable");
		sb.AppendLine();
		sb.AppendLine("namespace System.Runtime.CompilerServices");
		sb.AppendLine("{");
		sb.AppendLine("\t[global::System.AttributeUsage(global::System.AttributeTargets.Method, AllowMultiple = true)]");
		sb.AppendLine("\tfile sealed class InterceptsLocationAttribute(int version, string data) : global::System.Attribute { }");
		sb.AppendLine("}");
		sb.AppendLine();
		sb.AppendLine("namespace Open.Database.Extensions.Generated");
		sb.AppendLine("{");

		if (options.Counters) EmitCounters(sb);

		// One binder per model type, in a stable order.
		var models = new List<ModelSpec>();
		var ids = new Dictionary<ModelSpec, string>();
		foreach (Site s in sites)
		{
			if (ids.ContainsKey(s.Model)) continue;
			ids.Add(s.Model, "");
			models.Add(s.Model);
		}

		models.Sort((a, b) => string.CompareOrdinal(a.Type, b.Type));
		for (int i = 0; i < models.Count; i++) ids[models[i]] = "M" + i + "_" + Identifier(models[i].Type);

		EmitInterceptors(sb, sites, ids, options);
		EmitShared(sb);
		foreach (ModelSpec m in models) EmitModel(sb, m, ids[m], options);

		sb.AppendLine("}");
		return sb.ToString();
	}

	static string Identifier(string type)
	{
		int start = type.LastIndexOf('.') + 1;
		var sb = new StringBuilder();
		foreach (char c in type.Substring(start))
			sb.Append(char.IsLetterOrDigit(c) ? c : '_');

		return sb.ToString();
	}

	static void EmitCounters(StringBuilder sb)
	{
		sb.AppendLine("\t/// <summary>Test-only counters (OdxGeneratorCounters=true): how often the generated code was called and what it did. Never in a shipped build.</summary>");
		sb.AppendLine("\tpublic static class OdxGeneratedCounters");
		sb.AppendLine("\t{");
		sb.AppendLine("\t\t/// <summary>Interceptor calls (a Map&lt;T&gt;() call that ran the generated code).</summary>");
		sb.AppendLine("\t\tpublic static long Intercepted;");
		sb.AppendLine("\t\t/// <summary>Result sets bound and served by generated row readers.</summary>");
		sb.AppendLine("\t\tpublic static long Served;");
		sb.AppendLine("\t\t/// <summary>Result sets bound and declined to the runtime map.</summary>");
		sb.AppendLine("\t\tpublic static long Declined;");
		sb.AppendLine("\t\t/// <summary>Rows read by generated row readers.</summary>");
		sb.AppendLine("\t\tpublic static long RowsServed;");
		sb.AppendLine("\t\t/// <summary>Result sets bound, by read mode: 0 runtime, 1 full, 2 guarded, 3 constant ordinals, 4 full with converting reads, 5 identity (constant ordinals).</summary>");
		sb.AppendLine("\t\tpublic static readonly long[] Modes = new long[6];");
		sb.AppendLine("\t}");
		sb.AppendLine();
	}

	static void EmitInterceptors(StringBuilder sb, IReadOnlyList<Site> sites, Dictionary<ModelSpec, string> ids, Options options)
	{
		sb.AppendLine("\tfile static class OdxInterceptors");
		sb.AppendLine("\t{");
		for (int i = 0; i < sites.Count; i++)
		{
			Site s = sites[i];
			sb.AppendLine($"\t\t[global::System.Runtime.CompilerServices.InterceptsLocation({s.Version}, \"{s.Data}\")]");
			sb.AppendLine($"\t\tpublic static {s.ReturnType} Map_{i}(this {s.ReceiverType} source)");
			sb.AppendLine("\t\t{");
			if (options.Counters) sb.AppendLine("\t\t\tglobal::System.Threading.Interlocked.Increment(ref OdxGeneratedCounters.Intercepted);");
			sb.AppendLine($"\t\t\treturn {Ns}.CoreExtensions.Map<{s.Model.Type}>(source, (global::System.Func<{Record}, {s.Model.Type}>)new {ids[s.Model]}().Row);");
			sb.AppendLine("\t\t}");
			sb.AppendLine();
		}

		sb.AppendLine("\t}");
		sb.AppendLine();
	}

	// What every model shares: the slot table entry, the layout base, and RowMap.Match for a map with no pairs.
	static void EmitShared(StringBuilder sb) => sb.AppendLine(
"""
	// What one slot declares, for the matcher (RowMap's Slot, for a map with no pairs).
	file sealed class OdxSlot(string name, string column, int order, bool notMapped, bool required)
	{
		public readonly string Name = name;
		public readonly string Column = column;
		public readonly int Order = order;
		public readonly bool NotMapped = notMapped;
		public readonly bool Required = required;
	}

	// One result-set layout: the names and reported types (RowMap's Layout), and what the generated code does with it.
	file abstract class OdxLayout
	{
		public readonly string[] Names;
		public readonly global::System.Type[] Types;

		// 0: the runtime map serves it. 1: every slot fed in ascending column order, every read exact (no presence test).
		// 2: some slots absent, or the columns not in slot order (guarded, read in column order).
		// 3: as 1, at the constant ordinals the members declare ([Column(Order = n)]), read in Order.
		// 4: as 1, with a converting read chosen per column once per layout (a switch on it per cell, no presence test).
		// 5: as 1, each slot at its declaration position among the mapped slots (columns 0..n-1, more columns after them ignored): constant ordinals,
		//    for a model that does not declare its ordinals. The common shape (SELECT the members in their order) reads like a hand-written selector.
		public int Mode;

		// The column of each slot, -1 for none (in slot order); null when the runtime serves the layout.
		public int[] Ordinals;

		// The fed slots in column order: the order a guarded read takes, as the runtime reads and sets (and a SequentialAccess reader needs).
		public int[] Sequence;

		protected OdxLayout(global::System.Data.IDataRecord r)
		{
			int n = r.FieldCount;
			Names = new string[n];
			Types = new global::System.Type[n];
			for (int i = 0; i < n; i++)
			{
				Names[i] = r.GetName(i);
				Types[i] = r.GetFieldType(i) ?? typeof(object); // As the runtime: tolerant of a provider that reports no type.
			}
		}

		public bool Matches(global::System.Data.Common.DbDataReader r)
		{
			string[] names = Names;
			global::System.Type[] types = Types;
			if (r.FieldCount != names.Length) return false;
			for (int i = 0; i < names.Length; i++)
			{
				if (!string.Equals(r.GetName(i), names[i], global::System.StringComparison.Ordinal) || (r.GetFieldType(i) ?? typeof(object)) != types[i])
					return false;
			}

			return true;
		}
	}

	file static class OdxMatch
	{
		// The fed slots (a column, mapped) ordered by their column.
		public static int[] Sequence(int[] ordinals, OdxSlot[] slots)
		{
			int n = 0;
			for (int k = 0; k < ordinals.Length; k++)
				if (ordinals[k] >= 0 && !slots[k].NotMapped) n++;

			int[] sequence = new int[n], columns = new int[n];
			n = 0;
			for (int k = 0; k < ordinals.Length; k++)
			{
				if (ordinals[k] < 0 || slots[k].NotMapped) continue;
				sequence[n] = k;
				columns[n++] = ordinals[k];
			}

			global::System.Array.Sort(columns, sequence);
			return sequence;
		}

		// RowMap.Match, ClaimOrdinals and RequireColumns for a map with no pairs: the column of each slot (-1: none),
		// or null when the runtime would throw for this result set (a declared ordinal or column that is not there, a required member with no column).
		public static int[] Slots(string[] names, OdxSlot[] slots, bool decorated)
		{
			int n = slots.Length;
			int[] feeds = new int[names.Length];
			for (int i = 0; i < feeds.Length; i++) feeds[i] = -1;
			bool[] filled = new bool[n];
			string[] columns = new string[n];
			for (int p = 0; p < n; p++) columns[p] = slots[p].NotMapped ? null : slots[p].Column ?? slots[p].Name;

			int claimed = 0;
			if (decorated)
			{
				for (int p = 0; p < n; p++)
				{
					OdxSlot slot = slots[p];
					if (slot.Order < 0) continue;

					string expected = columns[p] ?? slot.Name;
					if (slot.Order >= names.Length || !string.Equals(names[slot.Order], expected, global::System.StringComparison.OrdinalIgnoreCase)) return null;

					feeds[slot.Order] = p;
					filled[p] = true;
					claimed++;
				}
			}

			int unmatched = names.Length - claimed - Feed(Index(columns, slots, decorated, global::System.StringComparer.Ordinal), names, feeds, filled);
			if (unmatched > 0) unmatched -= Feed(Index(columns, slots, decorated, global::System.StringComparer.OrdinalIgnoreCase), names, feeds, filled);
			if (unmatched > 0 && NameIndex(slots, filled) is { } byName) Feed(byName, names, feeds, filled);

			for (int p = 0; p < n; p++)
				if ((slots[p].Required || slots[p].Column != null) && !filled[p]) return null;

			int[] ordinals = new int[n];
			for (int p = 0; p < n; p++) ordinals[p] = -1;
			for (int i = 0; i < feeds.Length; i++)
				if (feeds[i] >= 0) ordinals[feeds[i]] = i;

			return ordinals;
		}

		static int Feed(global::System.Collections.Generic.Dictionary<string, int> index, string[] names, int[] feeds, bool[] filled)
		{
			int fed = 0;
			for (int i = 0; i < names.Length; i++)
			{
				if (feeds[i] >= 0 || names[i] == null || !index.TryGetValue(names[i], out int p) || filled[p]) continue;

				filled[p] = true;
				feeds[i] = p;
				fed++;
			}

			return fed;
		}

		static global::System.Collections.Generic.Dictionary<string, int> Index(string[] columns, OdxSlot[] slots, bool decorated, global::System.StringComparer comparer)
		{
			var index = new global::System.Collections.Generic.Dictionary<string, int>(columns.Length, comparer);
			if (decorated)
			{
				for (int p = 0; p < columns.Length; p++)
					if (slots[p].Column != null && columns[p] is { } declared && !index.ContainsKey(declared)) index.Add(declared, p);
			}

			for (int p = 0; p < columns.Length; p++)
				if (columns[p] is { } column && !index.ContainsKey(column)) index.Add(column, p);

			return index;
		}

		static global::System.Collections.Generic.Dictionary<string, int> NameIndex(OdxSlot[] slots, bool[] filled)
		{
			global::System.Collections.Generic.Dictionary<string, int> index = null;
			for (int p = 0; p < slots.Length; p++)
			{
				if (filled[p] || slots[p].Column != null || slots[p].NotMapped) continue;

				index ??= new(slots.Length, IgnoreCaseAndUnderscores.Instance);
				if (!index.ContainsKey(slots[p].Name)) index.Add(slots[p].Name, p);
			}

			return index;
		}

		sealed class IgnoreCaseAndUnderscores : global::System.Collections.Generic.IEqualityComparer<string>
		{
			public static readonly IgnoreCaseAndUnderscores Instance = new();

			public bool Equals(string x, string y)
			{
				if (ReferenceEquals(x, y)) return true;
				if (x is null || y is null) return false;

				int i = 0, j = 0;
				while (true)
				{
					while (i < x.Length && x[i] == '_') i++;
					while (j < y.Length && y[j] == '_') j++;
					if (i == x.Length || j == y.Length) return i == x.Length && j == y.Length;
					if (char.ToUpperInvariant(x[i++]) != char.ToUpperInvariant(y[j++])) return false;
				}
			}

			public int GetHashCode(string name)
			{
				int hash = 17;
				foreach (char c in name)
					if (c != '_') hash = unchecked(hash * 31 + char.ToUpperInvariant(c));

				return hash;
			}
		}

		// Shape.TypeName: Int32, Int32? for a Nullable<T>.
		public static string TypeName(global::System.Type type)
			=> global::System.Nullable.GetUnderlyingType(type) is { } underlying ? underlying.Name + "?" : type.Name;

		// RowMap.Guard's filter: the provider's own failures and cancellation propagate untouched; everything else is attributed.
		public static bool Wraps(global::System.Exception ex)
			=> ex is not global::System.Data.Common.DbException && ex is not global::System.OperationCanceledException;

		// The report of a row the generated reader could not map (cold, no reader work): the model type and the row (0-based among the rows this map
		// read), worded by the TYPE of the exception inside, which is kept: SqlClient's SqlNullValueException is a NULL read (ProviderNullTests);
		// InvalidCastException is a NULL or a column of another type (a DataTable reader, a cast of GetValue); anything else is not classified
		// (Microsoft.Data.Sqlite's NULL read is an InvalidOperationException, a type its other failures share). Never a member or column.
		public static global::System.Exception RowError(global::System.Exception ex, global::System.Type model, int row)
		{
			string name = TypeName(model);
			string message = ex is global::System.Data.SqlTypes.SqlNullValueException
				? $"A NULL was read into a non-nullable member of {name} at row {row}. Declare the member nullable (int?, string?)."
				: ex is global::System.InvalidCastException
					? $"A value at row {row} could not be read into a member of {name}: either a NULL in a non-nullable member (declare the member nullable: int?, string?) or a column whose type does not match the member."
					: $"Unable to map row {row} to '{name}'.";
			return new global::Open.Database.Extensions.ValueMappingException(message, "", "", model, ex);
		}
	}

""");

	static void EmitModel(StringBuilder sb, ModelSpec m, string id, Options options)
	{
		string T = m.Type;
		var slots = m.Slots.Items;
		bool styleB = m.UseConstructor || slots.Any(s => s.InitBound && !s.NotMapped);
		int[] literal = LiteralOrdinals(m);

		sb.AppendLine($"\t// {T}");
		sb.AppendLine($"\tfile sealed class {id}");
		sb.AppendLine("\t{");

		// ---- the slot table ----
		sb.AppendLine("\t\tstatic readonly OdxSlot[] Slots =");
		sb.AppendLine("\t\t[");
		foreach (SlotSpec s in slots)
			sb.AppendLine($"\t\t\tnew({Str(s.Name)}, {Str(s.Column)}, {s.Order}, {Bool(s.NotMapped)}, {Bool(s.Required)}),");
		sb.AppendLine("\t\t];");
		sb.AppendLine();
		sb.AppendLine($"\t\tstatic readonly {TypeT}[] SlotTypes = [{string.Join(", ", slots.Select(s => "typeof(" + s.Type + ")"))}];");
		sb.AppendLine($"\t\tstatic readonly string[] SlotParameters = [{string.Join(", ", slots.Select(s => Str(s.Parameter)))}];");
		sb.AppendLine();

		// ---- the read cases of each slot ----
		for (int k = 0; k < slots.Length; k++)
		{
			SlotSpec s = slots[k];
			if (s.NotMapped) continue;

			var cases = s.Cases.Items;
			string body = cases.Length == 0
				? "-1"
				: string.Join(" : ", cases.Select((c, i) => $"t == typeof({c.ColumnType}) ? {i}")) + " : -1";
			sb.AppendLine($"\t\tstatic int Case{k}({TypeT} t) => {body};");
		}

		sb.AppendLine();

		// ---- the layout ----
		sb.AppendLine("\t\tsealed class Layout : OdxLayout");
		sb.AppendLine("\t\t{");
		if (slots.Length > 0)
		{
			sb.AppendLine($"\t\t\tpublic int {string.Join(", ", Enumerable.Range(0, slots.Length).Select(k => "O" + k))};");
			sb.AppendLine($"\t\t\tpublic int {string.Join(", ", Enumerable.Range(0, slots.Length).Select(k => "C" + k))};");
		}

		sb.AppendLine($"\t\t\tpublic Layout({Record} r) : base(r) {{ }}");
		sb.AppendLine("\t\t}");
		sb.AppendLine();

		// The layouts met lately (a few, as queries over one model with different column lists alternate); a slot is replaced in turn. References are swapped atomically.
		sb.AppendLine("\t\tstatic readonly Layout[] s_layouts = new Layout[8];");
		sb.AppendLine("\t\tstatic int s_next;");
		sb.AppendLine();

		// Resolve: once per new result-set layout.
		sb.AppendLine($"\t\tstatic Layout Resolve({DbReader} r)");
		sb.AppendLine("\t\t{");
		sb.AppendLine("\t\t\tvar l = new Layout(r);");
		sb.AppendLine($"\t\t\tint[] o = OdxMatch.Slots(l.Names, Slots, {Bool(m.Decorated)});");
		sb.AppendLine("\t\t\tif (o == null) return l; // A check the runtime throws for: it serves (throws) it.");
		sb.AppendLine("\t\t\tbool full = true, exact = true, literal = true, ascending = true;");
		sb.AppendLine("\t\t\tint last = -1;");
		for (int k = 0; k < slots.Length; k++)
		{
			SlotSpec s = slots[k];
			if (s.NotMapped)
			{
				sb.AppendLine($"\t\t\tl.O{k} = -1; l.C{k} = -1;");
				continue;
			}

			sb.AppendLine($"\t\t\tl.O{k} = o[{k}];");
			sb.AppendLine($"\t\t\tif (o[{k}] >= 0)");
			sb.AppendLine("\t\t\t{");
			sb.AppendLine($"\t\t\t\tif ((l.C{k} = Case{k}(l.Types[o[{k}]])) < 0) return l; // A read the generated code does not make.");
			sb.AppendLine($"\t\t\t\tif (o[{k}] <= last) ascending = false;");
			sb.AppendLine($"\t\t\t\tlast = o[{k}];");
			sb.AppendLine($"\t\t\t\tif (l.C{k} != 0) exact = false;");
			sb.AppendLine($"\t\t\t\tif (o[{k}] != {literal[k]}) literal = false;");
			sb.AppendLine("\t\t\t}");
			sb.AppendLine("\t\t\telse");
			sb.AppendLine("\t\t\t{");
			if (s.InitBound)
				sb.AppendLine("\t\t\t\treturn l; // An init-only member with no column keeps what its type gives it, which an object initializer cannot leave alone.");
			else
				sb.AppendLine($"\t\t\t\tl.C{k} = -1; full = false;");
			sb.AppendLine("\t\t\t}");
		}

		sb.AppendLine("\t\t\tl.Ordinals = o;");
		// Every slot fed: constant ordinals when each sits at its declared Order (3, read in Order, which is column order) or, for a model that does not
		// declare its ordinals, at its declaration position (5, the identity: read in slot order, which is column order); else, in ascending column order,
		// exact reads (1) or a converting read chosen per column (4). Anything else is guarded (2), read in column order.
		sb.AppendLine(m.AllOrdered
			? "\t\t\tl.Mode = !full ? 2 : exact && literal ? 3 : !ascending ? 2 : exact ? 1 : 4;"
			: "\t\t\tl.Mode = !full || !ascending ? 2 : exact ? literal ? 5 : 1 : 4;");
		sb.AppendLine("\t\t\tif (l.Mode == 2) l.Sequence = OdxMatch.Sequence(o, Slots);");
		sb.AppendLine("\t\t\treturn l;");
		sb.AppendLine("\t\t}");
		sb.AppendLine();

		// The runtime's row reader for object[] rows: the default RowMap<T>'s array mapper (public, hidden from IntelliSense).
		sb.AppendLine("\t\tstatic class Runtime");
		sb.AppendLine("\t\t{");
		sb.AppendLine($"\t\t\tpublic static global::System.Func<object[], {T}> For(string[] names) => {Ns}.RowMap<{T}>.Default.ArrayMapper(global::System.Collections.Immutable.ImmutableArray.Create(names));");
		sb.AppendLine("\t\t}");
		sb.AppendLine();

		// The binding of one reader (one result set).
		sb.AppendLine("\t\tsealed class Bound");
		sb.AppendLine("\t\t{");
		sb.AppendLine($"\t\t\tpublic readonly {Record} Record;");
		sb.AppendLine($"\t\t\tpublic readonly {DbReader} Reader;");
		sb.AppendLine("\t\t\tpublic readonly Layout Layout;");
		sb.AppendLine($"\t\t\tglobal::System.Func<object[], {T}> _runtime;");
		sb.AppendLine("\t\t\tobject[] _row;");
		sb.AppendLine();
		sb.AppendLine("\t\t\t// The rows this binding has started (Row counts each before reading it): the row in flight is Rows - 1, the index a failure reports.");
		sb.AppendLine("\t\t\t// A new binding (another reader, a new execution of the same query, or a next result set with another column count) starts at 0.");
		sb.AppendLine("\t\t\tpublic int Rows;");
		sb.AppendLine();
		sb.AppendLine($"\t\t\tpublic Bound({Record} record, {DbReader} reader, Layout layout)");
		sb.AppendLine("\t\t\t{");
		sb.AppendLine("\t\t\t\tRecord = record;");
		sb.AppendLine("\t\t\t\tReader = reader;");
		sb.AppendLine("\t\t\t\tLayout = layout;");
		if (options.Counters)
		{
			sb.AppendLine("\t\t\t\tglobal::System.Threading.Interlocked.Increment(ref layout.Mode == 0 ? ref OdxGeneratedCounters.Declined : ref OdxGeneratedCounters.Served);");
			sb.AppendLine("\t\t\t\tglobal::System.Threading.Interlocked.Increment(ref OdxGeneratedCounters.Modes[layout.Mode]);");
		}

		sb.AppendLine("\t\t\t\t// A declined layout builds the runtime's reader now, at the first row, where the runtime builds (or throws) its own.");
		sb.AppendLine("\t\t\t\tif (layout.Mode == 0) _runtime = Runtime.For(layout.Names);");
		sb.AppendLine("\t\t\t}");
		sb.AppendLine();
		sb.AppendLine($"\t\t\tpublic {T} ByRuntime()");
		sb.AppendLine("\t\t\t{");
		sb.AppendLine("\t\t\t\tvar map = _runtime ??= Runtime.For(Layout.Names);");
		sb.AppendLine("\t\t\t\tvar row = _row ??= new object[Layout.Names.Length];");
		sb.AppendLine("\t\t\t\tRecord.GetValues(row);");
		sb.AppendLine("\t\t\t\treturn map(row);");
		sb.AppendLine("\t\t\t}");
		sb.AppendLine("\t\t}");
		sb.AppendLine();

		sb.AppendLine("\t\tBound _bound;");
		sb.AppendLine();

		// Row: the selector.
		sb.AppendLine($"\t\tpublic {T} Row({Record} record)");
		sb.AppendLine("\t\t{");
		sb.AppendLine("\t\t\tBound b = _bound;");
		// Bound once per reader, and again when the reader's column count changes: a reader view run again after NextResult (same reader) meets the new set.
		// A new set with the same column count on the same reader keeps the binding (no per-row layout check; a Core hook per result set would close this).
		sb.AppendLine("\t\t\tif (b == null || !ReferenceEquals(b.Record, record) || record.FieldCount != b.Layout.Names.Length) _bound = b = Bind(record);");
		if (options.Counters) sb.AppendLine("\t\t\tif (b.Layout.Mode != 0) global::System.Threading.Interlocked.Increment(ref OdxGeneratedCounters.RowsServed);");
		sb.AppendLine("\t\t\tb.Rows++;");
		sb.AppendLine("\t\t\tswitch (b.Layout.Mode)");
		sb.AppendLine("\t\t\t{");
		sb.AppendLine(m.AllOrdered ? "\t\t\t\tcase 3: return ReadLiteral(b);" : "\t\t\t\tcase 5: return ReadLiteral(b);");
		sb.AppendLine("\t\t\t\tcase 1: return ReadFull(b);");
		sb.AppendLine("\t\t\t\tcase 2: return ReadGuarded(b);");
		sb.AppendLine("\t\t\t\tcase 4: return ReadConverting(b);");
		sb.AppendLine("\t\t\t\tdefault: return b.ByRuntime();");
		sb.AppendLine("\t\t\t}");
		sb.AppendLine("\t\t}");
		sb.AppendLine();

		sb.AppendLine($"\t\tstatic Bound Bind({Record} record)");
		sb.AppendLine("\t\t{");
		sb.AppendLine($"\t\t\tif (record is {DbReader} r)");
		sb.AppendLine("\t\t\t{");
		sb.AppendLine("\t\t\t\tLayout[] layouts = s_layouts;");
		sb.AppendLine("\t\t\t\tfor (int i = 0; i < layouts.Length; i++)");
		sb.AppendLine("\t\t\t\t{");
		sb.AppendLine("\t\t\t\t\tLayout known = global::System.Threading.Volatile.Read(ref layouts[i]);");
		sb.AppendLine("\t\t\t\t\tif (known != null && known.Matches(r)) return new Bound(record, r, known);");
		sb.AppendLine("\t\t\t\t}");
		sb.AppendLine();
		sb.AppendLine("\t\t\t\tLayout l = Resolve(r);");
		sb.AppendLine("\t\t\t\tglobal::System.Threading.Volatile.Write(ref layouts[(int)((uint)global::System.Threading.Interlocked.Increment(ref s_next) % (uint)layouts.Length)], l);");
		sb.AppendLine("\t\t\t\treturn new Bound(record, r, l);");
		sb.AppendLine("\t\t\t}");
		sb.AppendLine();
		sb.AppendLine("\t\t\treturn new Bound(record, null, new Layout(record)); // Not a DbDataReader: the runtime serves it.");
		sb.AppendLine("\t\t}");
		sb.AppendLine();

		// The error for a row that failed (cold: only the row reader's one handler calls it, and it does no reader work): the model type and the row,
		// the provider's (or the model's) exception inside. No member or column: the row has one try region, so which cell failed is not tracked
		// (the runtime map names it; the generated reader keeps the hot path free of that bookkeeping). The same on every reader, SequentialAccess too.
		sb.AppendLine($"\t\tstatic global::System.Exception Fail(global::System.Exception ex, Bound b) => OdxMatch.RowError(ex, typeof({T}), b.Rows - 1);");
		sb.AppendLine();

		EmitRead(sb, m, "ReadLiteral", styleB, ReadMode.Literal, literal);
		EmitRead(sb, m, "ReadFull", styleB, ReadMode.Full, literal);
		EmitRead(sb, m, "ReadGuarded", styleB, ReadMode.Guarded, literal);
		EmitRead(sb, m, "ReadConverting", styleB, ReadMode.Converting, literal);

		sb.AppendLine("\t}");
		sb.AppendLine();
	}

	enum ReadMode { Literal, Full, Guarded, Converting }

	// The constant ordinal of each slot in the literal read mode, -1 for a slot not mapped: the declared Order of a model that declares every ordinal (mode 3),
	// else the slot's position among the mapped slots (mode 5, the identity). Resolve checks the layout against these before it chooses the mode.
	static int[] LiteralOrdinals(ModelSpec m)
	{
		var slots = m.Slots.Items;
		int[] literal = new int[slots.Length];
		int position = 0;
		for (int k = 0; k < slots.Length; k++)
		{
			if (slots[k].NotMapped) literal[k] = -1;
			else literal[k] = m.AllOrdered ? slots[k].Order : position++;
		}

		return literal;
	}

	// The order a mode reads (and sets) the slots in: by constant ordinal (column order), else slot order (ascending columns,
	// or any order for a guarded read, which walks Layout.Sequence instead).
	static IEnumerable<int> ReadOrder(System.Collections.Immutable.ImmutableArray<SlotSpec> slots, ReadMode mode, int[] literal)
	{
		IEnumerable<int> mapped = Enumerable.Range(0, slots.Length).Where(k => !slots[k].NotMapped);
		return mode == ReadMode.Literal ? mapped.OrderBy(k => literal[k]) : mapped;
	}

	// A member name as code: a keyword is escaped (@event).
	static string Code(string name)
		=> Microsoft.CodeAnalysis.CSharp.SyntaxFacts.GetKeywordKind(name) != Microsoft.CodeAnalysis.CSharp.SyntaxKind.None ? "@" + name : name;

	// A row reader: the whole row (reads, construction, sets) in one try region, entered once per row, whose cold handler names what failed (Fail).
	// RowMap.Guard's filter: the provider's DbException and a cancellation pass through untouched.
	static void EmitRead(StringBuilder sb, ModelSpec m, string name, bool styleB, ReadMode mode, int[] literal)
	{
		string T = m.Type;
		var slots = m.Slots.Items;
		string owner = T.Substring(T.LastIndexOf('.') + 1); // The model as its Debug.Assert messages name it.
		const string I = "\t\t\t\t";

		sb.AppendLine($"\t\tstatic {T} {name}(Bound b)");
		sb.AppendLine("\t\t{");
		sb.AppendLine($"\t\t\t{DbReader} r = b.Reader;");
		// The literal mode reads at constant ordinals: no layout in its rows.
		if (mode != ReadMode.Literal) sb.AppendLine("\t\t\tLayout l = b.Layout;");
		sb.AppendLine("\t\t\ttry");
		sb.AppendLine("\t\t\t{");

		if (!styleB)
		{
			// RowMap.CreateThenSet: new T(), then each fed cell read and set in column order (ascending: slot order).
			sb.AppendLine($"{I}var item = {m.Create};");
			string at = OpenSequence(sb, mode, I);
			foreach (int k in ReadOrder(slots, mode, literal))
			{
				SlotSpec s = slots[k];
				EmitSlot(sb, s, k, mode, at, literal[k], (read, general) => Statement(s, owner, "item." + Code(s.Name), read, general));
			}

			CloseSequence(sb, mode, I);
		}
		else
		{
			// RowMap.BindConstructor (and CreateThenSet for a model with init-only or required members): every fed cell read into a typed local
			// in column order (a parameter no column feeds passes its fallback), then the model is built, then the members the constructor does not
			// cover are set.
			for (int k = 0; k < slots.Length; k++)
			{
				SlotSpec s = slots[k];
				if (s.NotMapped) continue;

				sb.AppendLine($"{I}{s.Type} v{k} = {s.Fallback ?? "default(" + s.Type + ")"};");
			}

			string readAt = OpenSequence(sb, mode, I);
			foreach (int k in ReadOrder(slots, mode, literal))
			{
				SlotSpec s = slots[k];
				EmitSlot(sb, s, k, mode, readAt, literal[k], (read, general) => Statement(s, owner, "v" + k, read, general));
			}

			CloseSequence(sb, mode, I);

			var args = new string[m.ParameterCount];
			for (int k = 0; k < slots.Length; k++)
				if (slots[k].Position >= 0) args[slots[k].Position] = "v" + k;

			string create = m.UseConstructor ? $"new {T}({string.Join(", ", args)})" : m.Create;
			var inits = Enumerable.Range(0, slots.Length)
				.Where(k => slots[k].InitBound && !slots[k].NotMapped && slots[k].Position < 0)
				.Select(k => $"{Code(slots[k].Name)} = v{k}")
				.ToList();
			if (inits.Count > 0)
			{
				// An object initializer needs new T() spelled out; default(T) has none.
				if (!m.UseConstructor) create = "new " + T + "()";
				create += " { " + string.Join(", ", inits) + " }";
			}

			sb.AppendLine($"{I}var item = {create};");
			var sets = ReadOrder(slots, mode, literal)
				.Where(k => slots[k].Position < 0 && !slots[k].InitBound)
				.ToList();
			if (sets.Count > 0)
			{
				string setAt = OpenSequence(sb, mode, I);
				foreach (int k in sets)
				{
					string set = $"item.{Code(slots[k].Name)} = v{k};";
					if (mode == ReadMode.Guarded) sb.AppendLine($"{setAt}case {k}: {set} break;");
					else sb.AppendLine(setAt + set);
				}

				CloseSequence(sb, mode, I);
			}
		}

		sb.AppendLine($"{I}return item;");
		sb.AppendLine("\t\t\t}");
		sb.AppendLine("\t\t\tcatch (global::System.Exception ex) when (OdxMatch.Wraps(ex))");
		sb.AppendLine("\t\t\t{");
		sb.AppendLine("\t\t\t\tthrow Fail(ex, b);");
		sb.AppendLine("\t\t\t}");
		sb.AppendLine("\t\t}");
		sb.AppendLine();
	}

	// One slot's read: at a constant ordinal (Literal), the layout's (Full), or the layout's when the slot is fed, by the read case of its column
	// (Guarded, Converting).
	static void EmitSlot(StringBuilder sb, SlotSpec s, int k, ReadMode mode, string indent, int literal, Func<string, bool, string> statement)
	{
		var cases = s.Cases.Items;
		if (mode is ReadMode.Literal or ReadMode.Full || mode == ReadMode.Converting && cases.Length == 1)
		{
			string o = mode == ReadMode.Literal ? literal.ToString(System.Globalization.CultureInfo.InvariantCulture) : "l.O" + k;
			ReadCase c = cases[0];
			sb.AppendLine(indent + statement(c.General ? c.Expression : c.Expression.Replace("{0}", o), c.General).Replace("{O}", o));
			return;
		}

		// Guarded: inside the column-order loop (OpenSequence), this slot's case. Converting: every slot is fed, in ascending column order, so no presence test.
		// Either way the read case was chosen once per layout, by the column's type.
		if (mode == ReadMode.Guarded)
		{
			sb.AppendLine($"{indent}case {k}:");
			EmitCase(sb, s, k, indent + "\t", statement);
			sb.AppendLine($"{indent}\tbreak;");
		}
		else
		{
			sb.AppendLine($"{indent}// {s.Name}");
			EmitCase(sb, s, k, indent, statement);
		}
	}

	// A slot's read by the case its column's type chose: { int o = l.O{k}; switch (l.C{k}) { ... } }.
	static void EmitCase(StringBuilder sb, SlotSpec s, int k, string indent, Func<string, bool, string> statement)
	{
		var cases = s.Cases.Items;
		sb.AppendLine(indent + "{");
		sb.AppendLine(indent + $"\tint o = l.O{k};");
		sb.AppendLine(indent + $"\tswitch (l.C{k})");
		sb.AppendLine(indent + "\t{");
		for (int i = 0; i < cases.Length; i++)
		{
			ReadCase c = cases[i];
			string read = c.General ? c.Expression : c.Expression.Replace("{0}", "o");
			sb.AppendLine(indent + $"\t\tcase {i}: {statement(read, c.General).Replace("{O}", "o")} break;");
		}

		sb.AppendLine(indent + "\t}");
		sb.AppendLine(indent + "}");
	}

	// A guarded read walks the fed slots in column order (Layout.Sequence), one switch case per slot; the other modes read in slot order (their columns ascend).
	// Returns the indent of the cases.
	static string OpenSequence(StringBuilder sb, ReadMode mode, string indent)
	{
		if (mode != ReadMode.Guarded) return indent;

		sb.AppendLine(indent + "foreach (int k in l.Sequence)");
		sb.AppendLine(indent + "{");
		sb.AppendLine(indent + "\tswitch (k)");
		sb.AppendLine(indent + "\t{");
		return indent + "\t\t";
	}

	static void CloseSequence(StringBuilder sb, ReadMode mode, string indent)
	{
		if (mode != ReadMode.Guarded) return;

		sb.AppendLine(indent + "\t}");
		sb.AppendLine(indent + "}");
	}

	// The statement that reads a member's cell into its target (the property, or the local a constructor takes); {O} is the ordinal.
	// A member its type declares non-nullable is read alone (a general read casts GetValue), as a hand-written selector reads it: no IsDBNull, since a
	// NULL there is exceptional; the provider's typed getter throws on it (ProviderNullTests), or the cast of DBNull does, and the row's handler
	// reports it. A nullable member is tested for NULL first and gets null.
	// Before a non-nullable read, a Debug.Assert that the cell is not NULL: [Conditional("DEBUG")], so it is compiled into the consumer's Debug
	// builds only (a Release build has no trace of it, arguments included: GeneratedIlTests), where it names the member and the column at the
	// NULL even for a provider that would return a default silently.
	static string Statement(SlotSpec s, string owner, string target, string read, bool general)
	{
		if (s.NonNullable)
		{
			string assert = $"global::System.Diagnostics.Debug.Assert(!r.IsDBNull({{O}}), {Str(owner + "." + s.Name + " is non-nullable but column '")} + b.Layout.Names[{{O}}] + \"' is NULL at this row.\"); ";
			return assert + target + " = " + (general ? read.Replace("{0}", "r.GetValue({O})") : read) + ";";
		}

		if (general)
		{
			string value = read.Replace("{0}", "c");
			if (s.NullableValue) value = $"({s.Type})({value})";
			return $"{{ object c = r.GetValue({{O}}); {target} = c is null || c is global::System.DBNull ? default({s.Type}) : {value}; }}";
		}

		string present = s.NullableValue ? $"({s.Type})({read})" : read;
		return $"{target} = r.IsDBNull({{O}}) ? default({s.Type}) : {present};";
	}

	static string Str(string? s) => s is null ? "null" : Microsoft.CodeAnalysis.CSharp.SymbolDisplay.FormatLiteral(s, true);

	static string Bool(bool b) => b ? "true" : "false";
}
